import 'package:flutter/material.dart';
import 'package:simple_web_camera/simple_web_camera.dart';

class SimpleCameraExample extends StatelessWidget {
  const SimpleCameraExample({Key? key}) : super(key: key);

  @override
  Widget build(BuildContext context) {
    return ElevatedButton(
      onPressed: () async {
        var res = await Navigator.push(
          context,
          MaterialPageRoute(
            builder: (context) => const SimpleWebCameraPage(
                appBarTitle: "Take a Picture", centerTitle: true),
          ),
        );
      },
      child: const Text("Take a picture"),
    );
  }
}
